use std::fs
use std::collections::HashMap

struct Row {
    name: string,
    count: int,
    total: int,
    top: string,
}

fn all_digits(s: string) -> bool {
    if s.len() == 0 {
        return false
    }
    for c in s.chars() {
        if c < '0' || c > '9' {
            return false
        }
    }
    true
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut counts: HashMap<string, int> = HashMap::new()
    let mut totals: HashMap<string, int> = HashMap::new()
    let mut acts: HashMap<string, int> = HashMap::new()
    let mut bad = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split(" ").collect()
        if parts.len() != 3 || !all_digits(parts[2]) {
            bad += 1
            continue
        }
        let user = parts[0]
        let secs: int = parts[2].parse::<int>().unwrap_or(0)
        let c = counts.get(user).unwrap_or(0)
        counts.insert(user, c + 1)
        let t = totals.get(user).unwrap_or(0)
        totals.insert(user, t + secs)
        let key = "${user}\t${parts[1]}"
        let a = acts.get(key).unwrap_or(0)
        acts.insert(key, a + 1)
    }
    let mut rows: Vec<Row> = []
    for user in counts.keys() {
        let mut best = ""
        let mut bestn = 0
        for key in acts.keys() {
            let kp: Vec<string> = key.split("\t").collect()
            if kp[0] == user {
                let n = acts.get(key).unwrap_or(0)
                if n > bestn || (n == bestn && kp[1] < best) {
                    bestn = n
                    best = kp[1]
                }
            }
        }
        rows.push(Row { name: user, count: counts.get(user).unwrap_or(0), total: totals.get(user).unwrap_or(0), top: best })
    }
    rows.sort_by(|a, b| {
        if a.total != b.total {
            b.total.cmp(a.total)
        } else {
            a.name.cmp(b.name)
        }
    })
    for r in rows {
        println("${r.name} ${r.count} ${r.total} ${r.top}")
    }
    println("malformed: ${bad}")
}

